def commit_tags(sha1):
    # type: (str) -> List[str]
    """ Get the name of the tags that this commit belongs to. """
    tags = []
    for tag in git.tags():
        if tag.commit == sha1:
            tags.append(tag.name)
    return tags


def commit_parents(sha1):
    # type: (str) -> List[str]
    """ Get the name of the parents of this commit. """
    parents = []
    for parent in git.parents(sha1):
        parents.append(parent.hexsha)
    return parents


def commit_message(sha1):
    # type: (str) -> str
    """ Get the message of this commit. """
